function documentsView(){const d=state.detail,docs=d.documents.filter(doc=>state.episode==='all'||episodeOf(doc)===state.episode||episodeOf(doc)==='project'),selected=docs.find(item=>item.id===state.selectedDocument),isJson=selected?.id.endsWith('.json'),content=state.documentText?isJson&&state.documentMode==='structured'&&state.documentData!==null?renderDocument(state.documentData):`<pre>${esc(state.documentText)}</pre>`:'<div class="document-loading">正在读取…</div>';return `${topbar(`${d.project.title} / 分集与文档`,'分集与文档')}${episodeFilter(d)}<div class="document-layout"><section class="document-list">${docs.length?docs.map(doc=>`<button class="${doc.id===state.selectedDocument?'active':''}" data-document="${esc(doc.id)}"><small>${esc(doc.episodeKey||'项目')}</small><b>${esc(doc.label)}</b><span>${esc(doc.versionId)} · ${(doc.sizeBytes/1024).toFixed(1)} KB</span></button>`).join(''):empty('本分集暂无文档','切换分集或完成选版后会显示。')}</section><section class="document-preview">${selected?`<header><div><small>${esc(selected.episodeKey||'项目文档')}</small><h3>${esc(selected.label)} · ${esc(selected.versionId)}</h3></div><div class="document-actions">${isJson?`<div class="view-switch" aria-label="文档显示方式"><button class="${state.documentMode==='structured'?'active':''}" data-document-mode="structured">结构化</button><button class="${state.documentMode==='raw'?'active':''}" data-document-mode="raw">原始 JSON</button></div>`:''}<a class="secondary link-button" href="${esc(selected.contentUrl)}" target="_blank">原文件</a></div></header>${content}`:empty('选择文档','在左侧选择真实项目文档。')}</section></div>`}
