async function showProviderSetupOnce(){
  if(!['image','video','audio','music'].some(type=>!state.detail.project.providers?.[type]?.provider))return
  const key=providerPromptKey(state.detail.project.key)
  if(promptedProjects.has(key))return
  try{if(localStorage.getItem(key))return}catch{}
  await showProviderSetup()
  promptedProjects.add(key)
  try{localStorage.setItem(key,'1')}catch{}
}
async function openProject(key,view='overview',{route=true,prompt=true}={}){try{state.detail=await api(`/api/v1/projects/${encodeURIComponent(key)}`);Object.assign(state,{view,filter:'all',query:'',episode:'all',selectedAsset:null,selectedVersion:null,selectedDocument:null,documentText:'',documentData:null,documentMode:'structured',validation:null});if(route)pushRoute(projectRoute(key,view));renderProject();if(prompt)await showProviderSetupOnce()}catch(error){notify(error.message)}}
async function deleteProject(){const {key,title}=state.detail.project;if(state.detail.project.automation_mode!==true&&prompt(`删除“${title}”将永久移除全部项目文件。\n请输入项目 Key 确认：${key}`)!==key)return notify('项目 Key 不匹配，已取消删除');try{await api(`/api/v1/projects/${encodeURIComponent(key)}`,{method:'DELETE',headers:{'x-short-drama-csrf':state.bootstrap.csrfToken,'x-short-drama-confirmed':'true'}});state.detail=null;state.bootstrap=await api('/api/v1/workspace');replaceRoute('#/');try{localStorage.removeItem(providerPromptKey(key))}catch{}overview();notify('项目已删除')}catch(error){notify(error.message)}}
async function loadDocument(id){const doc=state.detail.documents.find(item=>item.id===id);if(!doc)return;Object.assign(state,{selectedDocument:id,documentText:'',documentData:null,documentMode:'structured'});renderProject();try{const response=await fetch(doc.contentUrl);if(!response.ok)throw new Error('文档读取失败');state.documentText=await response.text();if(doc.id.endsWith('.json'))try{state.documentData=JSON.parse(state.documentText)}catch{state.documentMode='raw';notify('JSON 格式异常，已显示原始内容')}renderProject()}catch(error){notify(error.message)}}
async function mutateAsset(asset,action,payload){try{state.detail=await api(`/api/v1/projects/${encodeURIComponent(state.detail.project.key)}/assets/${encodeURIComponent(asset.key)}/${action}`,{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify(payload)});renderProject();notify(action==='select'?'选版已更新':'已撤回最近一次选版')}catch(error){notify(error.message)}}
let refreshing=false
async function refreshAll(){
  if(refreshing)return
  refreshing=true
  try{
    const key=state.detail?.project.key,document=state.detail?.documents.find(item=>item.id===state.selectedDocument)
    const results=await Promise.allSettled([api('/api/v1/workspace'),key?api(`/api/v1/projects/${encodeURIComponent(key)}`):null,api('/api/v1/providers').then(data=>data.providers),key&&state.validation?api(`/api/v1/projects/${encodeURIComponent(key)}/validation`):null,document?fetch(document.contentUrl):null])
    const [bootstrap,detail,providers,validation,documentResponse]=results.map(result=>result.status==='fulfilled'?result.value:null)
    let changed=false
    if(bootstrap){changed=JSON.stringify(state.bootstrap)!==JSON.stringify(bootstrap);state.bootstrap=bootstrap}
    if(providers)state.providerCatalog=providers
    if(detail&&state.detail?.project.key===key){changed ||= JSON.stringify(state.detail)!==JSON.stringify(detail);state.detail=detail}
    if(validation){changed ||= JSON.stringify(state.validation)!==JSON.stringify(validation);state.validation=validation}
    if(documentResponse?.ok){const text=await documentResponse.text();if(text!==state.documentText){state.documentText=text;if(document.id.endsWith('.json'))try{state.documentData=JSON.parse(text)}catch{state.documentData=null;state.documentMode='raw'}changed=true}}
    if(changed)state.detail?renderProject():overview()
    const failure=results.find(result=>result.status==='rejected')
    if(failure)notify(`自动刷新失败：${failure.reason.message}`)
  }finally{refreshing=false}
}
const valueAtPath=(value,path)=>path.split('.').reduce((current,part)=>current?.[Number.isInteger(Number(part))?Number(part):part],value)
async function generateMarketCandidates(){const reportId=state.market?.sourceReportId||marketReport()?.report_id;if(!reportId||!state.marketInspirationTopics.length||state.marketInspirationBusy)return;const requestId=state.marketInspirationRequest=beginMarketGeneration(state.marketInspirationRequest);state.marketInspirationBusy=true;renderMarket();try{const result=await api('/api/v1/market/inspirations/generate',{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify({reportId,topics:state.marketInspirationTopics})});if(!acceptMarketGeneration(requestId,state.marketInspirationRequest))return;state.marketCandidates=result.candidates;state.selectedMarketCandidate=result.candidates[0]?.id||null;if(!result.candidates.length)notify('当前题材没有可追溯证据，未生成候选')}catch(error){if(acceptMarketGeneration(requestId,state.marketInspirationRequest))notify(error.message)}finally{if(acceptMarketGeneration(requestId,state.marketInspirationRequest)){state.marketInspirationBusy=false;renderMarket()}}}
async function registerMarketCandidate(){if(!state.selectedMarketCandidate||!state.marketInspirationProject)return;state.marketInspirationBusy=true;renderMarket();try{await api('/api/v1/market/inspirations/register',{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify({projectKey:state.marketInspirationProject,candidateId:state.selectedMarketCandidate})});notify('市场灵感和 Brief 引用已登记')}catch(error){notify(error.message)}finally{state.marketInspirationBusy=false;renderMarket()}}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.marketHome!==undefined){event.stopImmediatePropagation();state.detail=null;pushRoute(marketRoute());loadMarket()}else if(target.dataset.marketRefresh!==undefined){event.stopImmediatePropagation();refreshMarket()}else if(target.dataset.marketTopicRow){event.stopImmediatePropagation();state.selectedMarketTopic=target.dataset.marketTopicRow;renderMarket()}else if(target.dataset.marketClose!==undefined){event.stopImmediatePropagation();state.selectedMarketTopic=null;renderMarket()}else if(target.dataset.marketClear!==undefined){event.stopImmediatePropagation();state.marketFilters={ranking:'all',topic:'all',audience:'all',format:'all'};loadMarket()}else if(target.dataset.marketReport){event.stopImmediatePropagation();state.selectedMarketReport=target.dataset.marketReport;state.selectedMarketTopic=null;Object.assign(state,resetMarketInspiration());state.marketInspirationRequest=beginMarketGeneration(state.marketInspirationRequest);loadMarket()}else if(target.dataset.marketInspirationTopic){event.stopImmediatePropagation();const topic=target.dataset.marketInspirationTopic,result=toggleMarketInspirationTopic(state.marketInspirationTopics,topic);if(result.limited)return notify('最多选择 3 个题材');Object.assign(state,resetMarketInspiration());state.marketInspirationTopics=result.topics;state.marketInspirationRequest=beginMarketGeneration(state.marketInspirationRequest);renderMarket()}else if(target.dataset.marketGenerate!==undefined){event.stopImmediatePropagation();generateMarketCandidates()}else if(target.dataset.marketCandidate){event.stopImmediatePropagation();state.selectedMarketCandidate=selectMarketCandidate(target.dataset.marketCandidate);renderMarket()}else if(target.dataset.marketRegister!==undefined){event.stopImmediatePropagation();registerMarketCandidate()}},true)
document.addEventListener('change',event=>{if(event.target.matches('[data-market-filter-key]')){state.marketFilters[event.target.dataset.marketFilterKey]=event.target.value;state.selectedMarketTopic=null;loadMarket()}else if(event.target.matches('[data-market-period]')){state.selectedMarketReport=event.target.value;state.selectedMarketTopic=null;Object.assign(state,resetMarketInspiration());state.marketInspirationRequest=beginMarketGeneration(state.marketInspirationRequest);loadMarket()}else if(event.target.matches('[data-market-sort]')){state.marketSort=event.target.value;renderMarket()}else if(event.target.matches('[data-market-inspiration-project]')){state.marketInspirationProject=event.target.value;renderMarket()}},true)
app.addEventListener('click',event=>{const target=event.target.closest('[data-delete-project]');if(!target)return;event.stopPropagation();deleteProject()})
document.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.close!==undefined)return createDialog.close();if(target.dataset.closeImport!==undefined)return importDialog.close();if(target.dataset.closeProvider!==undefined)return providerDialog.close();if(target.dataset.create!==undefined)return createDialog.showModal();if(target.dataset.import!==undefined)return importDialog.showModal();if(target.dataset.providers!==undefined){try{await showProviderSetup()}catch(error){notify(error.message)}return}if(target.dataset.saveCredential){const input=target.closest('.provider-card').querySelector('[data-credential]'),credential=input.value;if(!credential)return notify('请先输入凭据');target.disabled=true;try{await api(`/api/v1/providers/${encodeURIComponent(target.dataset.saveCredential)}/credential`,{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify({credential})});state.providerCatalog=null;await showProviderSetup();notify('凭据已保存到本机')}catch(error){notify(error.message)}finally{target.disabled=false}return}if(target.dataset.testProvider){const label=target.textContent;target.disabled=true;target.textContent='测试中…';try{const result=await api(`/api/v1/providers/${encodeURIComponent(target.dataset.testProvider)}/test`,{method:'POST',headers:{'x-short-drama-csrf':state.bootstrap.csrfToken}});target.classList.add('test-ok');target.textContent='✓ 连接成功';notify(result.message)}catch(error){target.classList.add('test-failed');target.textContent='测试失败';notify(error.message)}finally{setTimeout(()=>{target.disabled=false;target.classList.remove('test-ok','test-failed');target.textContent=label},3000)}return}if(target.dataset.closeCard!==undefined)return cardDialog.close();if(target.dataset.home!==undefined){state.detail=null;pushRoute('#/');return overview()}if(target.dataset.project)return openProject(target.dataset.project);if(target.dataset.view){state.view=target.dataset.view;pushRoute(projectRoute(state.detail.project.key,state.view));renderProject();if(state.view==='documents'&&!state.selectedDocument){const doc=state.detail.documents.find(item=>matchesEpisode(item,state.episode));if(doc)loadDocument(doc.id)}return}if(target.dataset.episode){state.episode=target.dataset.episode;state.selectedDocument=null;state.selectedAsset=null;renderProject();if(state.view==='documents'){const doc=state.detail.documents.find(item=>matchesEpisode(item,state.episode));if(doc)loadDocument(doc.id)}return}if(target.dataset.document)return loadDocument(target.dataset.document);if(target.dataset.docCard){const value=valueAtPath(state.documentData,target.dataset.docCard);cardTitle.textContent=value?.shot_number?`镜头 ${value.shot_number}`:value?.panel_number?`分镜 ${value.panel_number}`:'详情';cardContent.innerHTML=renderDocument(value);return cardDialog.showModal()}if(target.dataset.documentMode){state.documentMode=target.dataset.documentMode;return renderProject()}if(target.dataset.videoExpand!==undefined){const video=target.closest('.video-player')?.querySelector('video');if(video?.requestFullscreen)await video.requestFullscreen();return}if(target.dataset.filter){state.filter=target.dataset.filter;return renderProject()}if(target.dataset.asset){state.selectedAsset=target.dataset.asset;state.selectedVersion=null;return renderProject()}if(target.dataset.version){state.selectedVersion=target.dataset.version;return renderProject()}if(target.dataset.validate!==undefined){try{state.validation=await api(`/api/v1/projects/${encodeURIComponent(state.detail.project.key)}/validation`);renderProject();notify(state.validation.valid?'项目校验通过':`发现 ${state.validation.issues.length} 项问题`)}catch(error){notify(error.message)}return}const asset=state.detail?.assets.find(item=>item.key===state.selectedAsset);if(target.dataset.select!==undefined&&asset&&confirm(`确认将 ${state.selectedVersion} 设为 ${asset.name} 的当前版本？`))await mutateAsset(asset,'select',{versionId:state.selectedVersion,confirmed:true});if(target.dataset.revert!==undefined&&asset&&confirm(`确认撤回 ${asset.name} 最近一次选版？`))await mutateAsset(asset,'revert',{confirmed:true})})
const videoTime=seconds=>Number.isFinite(seconds)?`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`:'00:00'
const syncVideo=video=>{const player=video.closest('.video-player'),progress=player?.querySelector('[data-video-progress]');if(!progress)return;progress.value=video.duration?video.currentTime/video.duration*100:0;player.querySelector('[data-current]').textContent=videoTime(video.currentTime);player.querySelector('[data-duration]').textContent=videoTime(video.duration)}
app.addEventListener('input',event=>{if(event.target.matches('[data-search]')){state.query=event.target.value;renderProject();document.querySelector('[data-search]')?.focus()}if(event.target.matches('[data-video-progress]')){const video=event.target.closest('.video-player')?.querySelector('video');if(video?.duration)video.currentTime=video.duration*Number(event.target.value)/100}})
app.addEventListener('timeupdate',event=>{if(event.target.matches('.video-player video'))syncVideo(event.target)},true)
app.addEventListener('loadedmetadata',event=>{if(event.target.matches('.video-player video'))syncVideo(event.target)},true)
document.addEventListener('change',async event=>{if(!event.target.matches('[data-automation-toggle]'))return;const input=event.target;if(input.checked&&!window.confirm('启用后，本项目已配置 Provider 的常规生成将自动继续。确认授予该项目持续付费生成授权吗？')){input.checked=false;return}input.disabled=true;try{state.detail=await api(`/api/v1/projects/${encodeURIComponent(state.detail.project.key)}/automation`,{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify({enabled:input.checked,paidAuthorizationConfirmed:input.checked})});renderProject();notify(input.checked?'已开启全托管':'已关闭自动托管')}catch(error){input.checked=!input.checked;notify(error.message)}finally{input.disabled=false}})
createForm.addEventListener('change',event=>{if(event.target.name!=='workflowType')return;createForm.querySelector('[data-workflow-hint]').hidden=event.target.value!=='viral-recreation'})
providerForm.addEventListener('change',event=>{if(!event.target.matches('[data-model-select]'))return;const type=event.target.dataset.modelSelect;for(const group of providerForm.querySelectorAll(`[data-parameter-group="${type}"]`)){group.hidden=group.dataset.model!==event.target.value;for(const input of group.querySelectorAll('input,select'))input.disabled=group.hidden}})
providerForm.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(providerForm),providers={};for(const type of ['image','video','audio','music']){const [provider=null,model_or_workflow=null]=String(data.get(type)||'').split('|'),model=state.providerCatalog.find(item=>item.key===provider)?.models[type].find(item=>item.id===model_or_workflow),parameters={};for(const field of model?.parameters||[]){const name=`${type}.parameters.${field.key}`,raw=data.get(name);parameters[field.key]=field.type==='boolean'?data.has(name):field.type==='number'?Number(raw):raw}providers[type]={provider,model_or_workflow,parameters}}const styleId=data.get('art_style'),style=styleId?state.artStyles.find(item=>item.id===styleId):state.detail.project.creative?.art_style;if(!style)return notify('请选择画风');const submit=providerForm.querySelector('[type=submit]');submit.disabled=true;try{state.detail=await api(`/api/v1/projects/${encodeURIComponent(state.detail.project.key)}/providers`,{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify({providers,creative:{art_style:style}})});providerDialog.close();renderProject();notify('画风、生成配置与模型参数已保存')}catch(error){providerDialog.close();notify(error.message)}finally{submit.disabled=false}})
createForm.addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(createForm));for(const key of ['episodeCount','episodeDurationSeconds'])values[key]=values[key]?Number(values[key]):null;const submit=createForm.querySelector('[type=submit]');submit.disabled=true;try{const detail=await api('/api/v1/projects',{method:'POST',headers:{'content-type':'application/json','x-short-drama-csrf':state.bootstrap.csrfToken},body:JSON.stringify(values)});createDialog.close();createForm.reset();createForm.querySelector('[data-workflow-hint]').hidden=true;state.bootstrap=await api('/api/v1/workspace');state.detail=detail;state.view='overview';pushRoute(projectRoute(detail.project.key));renderProject();notify('项目已创建');await showProviderSetupOnce()}catch(error){notify(error.message)}finally{submit.disabled=false}})
importForm.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(importForm),file=data.get('file'),params=new URLSearchParams({assetKey:data.get('assetKey'),type:data.get('type'),name:data.get('name'),versionId:data.get('versionId'),filename:file.name});if(state.detail.project.automation_mode!==true&&!confirm(`确认导入 ${file.name}？文件将复制到项目资产目录。`))return;const submit=importForm.querySelector('[type=submit]');submit.disabled=true;try{state.detail=await api(`/api/v1/projects/${encodeURIComponent(state.detail.project.key)}/assets/import?${params}`,{method:'POST',headers:{'x-short-drama-csrf':state.bootstrap.csrfToken,'x-short-drama-confirmed':'true'},body:file});importDialog.close();importForm.reset();renderProject();notify('资产已导入')}catch(error){notify(error.message)}finally{submit.disabled=false}})
window.addEventListener('popstate',async()=>{const route=parseAppRoute(location.hash);if(route.kind==='market'){state.detail=null;await loadMarket()}else if(route.kind==='project')await openProject(route.projectKey,route.view,{route:false,prompt:false});else{state.detail=null;overview()}})
try{state.bootstrap=await api('/api/v1/workspace');const route=parseAppRoute(location.hash);if(route.kind==='market')await loadMarket();else if(route.kind==='project')await openProject(route.projectKey,route.view,{route:false});else{replaceRoute('#/');overview()}setInterval(refreshAll,refreshMs)}catch(error){app.innerHTML=empty('工作台无法启动',error.message)}
